import ApiService from './framework/api-service.js';

const Method = {
  GET: 'GET',
  PUT: 'PUT',
  POST: 'POST',
  DELETE: 'DELETE',
};

export default class TripApiService extends ApiService {
  get points() {
    return this._load({ url: 'points' }).then(ApiService.parseResponse);
  }

  get offers() {
    return this._load({ url: 'offers' }).then(ApiService.parseResponse);
  }

  get destinations() {
    return this._load({ url: 'destinations' }).then(ApiService.parseResponse);
  }

  async updatePoint(point) {
    const response = await this._load({
      url: `points/${point.id}`,
      method: Method.PUT,
      body: JSON.stringify(this.#adaptToServer(point)),
      headers: new Headers({ 'Content-Type': 'application/json' }),
    });

    const parsedResponse = await ApiService.parseResponse(response);

    return parsedResponse;
  }

  async addPoint(point) {
    const response = await this._load({
      url: 'points',
      method: Method.POST,
      body: JSON.stringify(this.#adaptToServer(point)),
      headers: new Headers({ 'Content-Type': 'application/json' }),
    });

    const parsedResponse = await ApiService.parseResponse(response);

    return parsedResponse;
  }

  async deletePoint(point) {
    const response = await this._load({
      url: `points/${point.id}`,
      method: Method.DELETE,
    });

    return response;
  }

  #adaptToServer(point) {
    const adaptedPoint = {
      ...point,
      destination: point.destinationId,
      offers: point.offersIds,
    };

    adaptedPoint['date_from'] = point.startDateTime;
    adaptedPoint['date_to'] = point.endDateTime;
    adaptedPoint['base_price'] = parseInt(point.price, 10);
    adaptedPoint['is_favorite'] = point.isFavorite;

    delete adaptedPoint.startDateTime;
    delete adaptedPoint.endDateTime;
    delete adaptedPoint.destinationId;
    delete adaptedPoint.price;
    delete adaptedPoint.offersIds;
    delete adaptedPoint.isFavorite;

    return adaptedPoint;
  }
}
